import { test, expect } from '@playwright/test';

test.describe('Background Job Toast Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display toast notification when background job completes', async ({ page }) => {
    // Click button to start background job
    const startJobButton = page.getByRole('button', { name: /start job/i });
    await startJobButton.click();

    // Wait for toast notification to appear
    const toast = page.getByRole('status');
    await expect(toast).toBeVisible({ timeout: 10000 });

    // Verify toast contains success message
    await expect(toast).toContainText(/job completed/i);
  });

  test('should display toast with correct completion message', async ({ page }) => {
    // Start the background job
    const startJobButton = page.getByRole('button', { name: /start job/i });
    await startJobButton.click();

    // Wait for and verify the toast notification content
    const toast = page.getByText(/successfully completed/i);
    await expect(toast).toBeVisible({ timeout: 10000 });

    // Verify toast is dismissible
    const closeButton = page.getByRole('button', { name: /close/i }).first();
    await closeButton.click();
    await expect(toast).not.toBeVisible();
  });

  test('should handle multiple background jobs with separate notifications', async ({ page }) => {
    // Start first job
    const startJobButton = page.getByRole('button', { name: /start job/i });
    await startJobButton.click();

    // Wait for first toast
    const firstToast = page.getByRole('status').first();
    await expect(firstToast).toBeVisible({ timeout: 10000 });

    // Start second job
    await startJobButton.click();

    // Wait for second toast
    const toasts = page.getByRole('status');
    await expect(toasts).toHaveCount(2, { timeout: 10000 });
  });
});
